const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>'₦'+Number(n).toLocaleString('en-NG'),date=s=>new Date(s).toLocaleDateString('en-NG',{day:'numeric',month:'short',year:'numeric'});
let state={user:null,settings:{},needsSetup:false},cakes=[],categories=[],cart=[],stream,filter='All',query='';try{cart=JSON.parse(localStorage.getItem('temmyd-cart-v2')||'[]');if(!Array.isArray(cart))cart=[]}catch{}let pageVersion=0;
async function api(url,opts={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...opts,body:opts.body?JSON.stringify(opts.body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed.');return d}
async function session(){state=await api('/api/session');if(state.user&&!stream){stream=new EventSource('/api/events');stream.onmessage=e=>{if(e.data==='update'&&(location.pathname.startsWith('/admin')||location.pathname.startsWith('/account/orders')))render()}}else if(!state.user&&stream){stream.close();stream=null}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function go(p){history.pushState({},'',p);render();window.scrollTo(0,0)}
function save(){localStorage.setItem('temmyd-cart-v2',JSON.stringify(cart))}const count=()=>cart.reduce((s,i)=>s+Number(i.qty||0),0);const logo=()=>'<span class="wordmark">temmyd<span>CAKES & A LITTLE MAGIC</span></span>';
const isStaff=()=>['admin','manager','delivery'].includes(state.user?.role);
function shell(content,active=''){return `<div class="topline">A little joy, baked in. <span>✦</span> Handcrafted for your happiest moments.</div><header><a href="/" data-link>${logo()}</a><nav><a data-link href="/shop" class="${active==='shop'?'active':''}">Shop cakes</a><a data-link href="/about">Our story</a><a data-link href="/account/orders">Track my order</a></nav><div class="header-actions">${state.user?`<a href="${isStaff()?'/admin':'/account'}" data-link>${isStaff()?'Bakery studio':'My account'}</a>`:'<a href="/login" data-link>Sign in</a>'}<a class="box-button" data-link href="/cart">Your box <b>${count()}</b> ↗</a></div></header><main>${content}</main><footer><a data-link href="/">${logo()}</a><p>A little joy, baked in.</p><div><a data-link href="/shop">Our cakes</a><a data-link href="/account/orders">Your orders</a><a data-link href="/admin">Admin studio</a></div><small>© ${new Date().getFullYear()} ${esc(state.settings.business_name)} · ${esc(state.settings.phone||'Baked to order')}</small></footer>`}
const title=(k,h,p='')=>`<div class="page-title"><div class="eyebrow">${k}</div><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>`;
const badge=s=>`<span class="badge ${['Delivered','Collected','Paid'].includes(s)?'green':['Cancelled','Refunded'].includes(s)?'red':['Baking','Out for delivery'].includes(s)?'amber':''}">${esc(s)}</span>`;
function cards(list){return list.map(c=>`<article class="cake-card"><a href="/cakes/${c.id}" data-link class="cake-photo"><img src="${esc(c.image)}" alt="${esc(c.name)}" loading="lazy">${c.featured?'<span class="cake-tag">BAKERY FAVOURITE</span>':''}<span class="circle-arrow">↗</span></a><div class="card-category">${esc(c.category)}</div><a href="/cakes/${c.id}" data-link><h3>${esc(c.name)}</h3></a><p>${esc(c.description)}</p><strong>${money(c.price)} <small>from</small></strong></article>`).join('')||'<div class="empty">No cakes match your search.</div>'}
async function home(){return shell(`<section class="hero"><div><div class="eyebrow">HAPPINESS, HANDCRAFTED</div><h1>For the moments<br>that deserve<br><em>something sweet.</em></h1><p>Thoughtfully made cakes. Beautiful little details. A whole lot of love in every slice.</p><a href="/shop" data-link class="button">Find your happy slice <span>↗</span></a><div class="handwritten">♡ Made for your kind of celebration.</div></div><div class="hero-image"><img src="${esc(cakes[0]?.image||'')}" alt="A handcrafted Temmyd celebration cake"><span class="seal">freshly baked<br><em>just for you</em><br>✦</span><div class="hero-image-label">GOOD DAYS START WITH CAKE.</div></div></section><div class="values">BAKED TO ORDER <span>✳</span> REAL INGREDIENTS <span>✳</span> BEAUTIFULLY HANDCRAFTED <span>✳</span> MADE WITH LOVE</div><section class="container section"><div class="section-heading"><div><div class="eyebrow">THE SWEETEST LINEUP</div><h2>A few crowd <em>favourites.</em></h2></div><a data-link href="/shop">Explore all cakes ↗</a></div><div class="cake-grid">${cards(cakes.filter(c=>c.featured).slice(0,3))}</div></section><section class="rose-panel"><div class="eyebrow">FROM OUR OVEN TO YOUR OCCASION</div><h2>More than a cake.<br>A moment to remember.</h2><p>Choose your cake, add your own message, and follow its journey from our kitchen to your celebration.</p><a data-link href="/shop" class="button">Let’s make it a sweet one ↗</a></section><section class="container steps"><article><span>01</span><h3>Make it yours</h3><p>Choose your flavour, size and a message from the heart.</p></article><article><span>02</span><h3>Pick your moment</h3><p>Tell us when and where. We’ll take care of the sweet details.</p></article><article><span>03</span><h3>Follow the magic</h3><p>Track your order as we prepare, bake and deliver it.</p></article></section>`)}
function shop(){const cats=['All',...categories.map(c=>c.name)];return shell(`<section class="container section">${title('FRESH FROM OUR KITCHEN','Find your next <em>favourite.</em>','Birthday joy, everyday treats, and everything in between.')}<div class="catalogue-tools"><div class="filters">${cats.map(c=>`<button class="${filter===c?'selected':''}" data-filter="${esc(c)}">${esc(c==='All'?'All cakes':c)}</button>`).join('')}</div><label class="search">⌕ <input id="cakeSearch" placeholder="Find a flavour…" aria-label="Search cakes" value="${esc(query)}"></label></div><div id="cakeResults" class="cake-grid">${cards(filtered())}</div><p class="fineprint">Our starter catalogue and prices are samples. Admin can replace every detail. Cakes contain dairy, eggs and wheat unless confirmed otherwise.</p></section>`,'shop')}
function filtered(){return cakes.filter(c=>(filter==='All'||c.category===filter)&&(c.name+' '+c.description).toLowerCase().includes(query.toLowerCase()))}
function product(cid){const c=cakes.find(c=>c.id===cid);if(!c)return shell(title('OH CRUMBS','This cake isn’t available.','Please choose another cake from our shop.'));return shell(`<section class="container section"><a class="back" data-link href="/shop">← Back to all cakes</a><div class="product-layout"><img class="detail-photo" src="${esc(c.image)}" alt="${esc(c.name)}"><div class="detail-copy"><div class="eyebrow">${esc(c.category)}</div><h1>${esc(c.name)}</h1><p>${esc(c.description)}</p><div class="product-price" id="productPrice">${money(c.price)}</div><form id="productForm"><label>Choose your size<select name="size"><option value="6">${c.category==='Cupcakes'?'Box of 6':'6 inch · serves approx. 6–8'}</option><option value="8">${c.category==='Cupcakes'?'Box of 9':'8 inch · serves approx. 10–14'}</option><option value="10">${c.category==='Cupcakes'?'Box of 12':'10 inch · serves approx. 18–22'}</option></select></label><div class="form-row"><label>Quantity<input type="number" name="qty" min="1" max="20" value="1" required></label><label>Your cake message<input name="message" maxlength="100" placeholder="Happy birthday, you!"></label></div><button class="button full">Add to your box ↗</button></form><div class="product-notes"><p>✧ Baked to order · ${esc(state.settings.lead_days)} days’ preparation</p><p>♡ Add a personal message at no extra cost</p><p>Contains dairy, eggs and wheat. Contact the bakery about dietary needs before placing an order.</p></div></div></div></section>`,'shop')}
function cartDetails(){return cart.map(i=>{const c=cakes.find(c=>c.id===i.cakeId);return {...i,c,unit:c?Math.round(c.price*({6:1,8:1.5,10:2}[i.size]||1)):0}})}
function cartPage(){const items=cartDetails(),total=items.reduce((n,i)=>n+i.unit*i.qty,0);return shell(`<section class="container section">${title('A BOX OF HAPPINESS','Your sweet selection.')} ${!cart.length?'<div class="empty"><span>♡</span><h2>Your box is waiting.</h2><p>Let’s find something delicious to put in it.</p><a class="button" data-link href="/shop">Explore our cakes ↗</a></div>':`<div class="checkout-layout"><div>${items.map((i,n)=>`<div class="cart-line"><img src="${esc(i.c?.image||'')}" alt=""><div><h3>${esc(i.c?.name||'Cake unavailable')}</h3><p>${i.size===6?'Small':i.size===8?'Medium':'Large'} · ${esc(i.message||'No cake message')}</p><div class="quantity"><button data-qty="${n}" data-delta="-1" aria-label="Decrease quantity">−</button><b>${i.qty}</b><button data-qty="${n}" data-delta="1" aria-label="Increase quantity">+</button><button data-remove="${n}" class="text-button">Remove</button></div></div><strong>${money(i.unit*i.qty)}</strong></div>`).join('')}</div><aside class="summary"><h3>Your box, at a glance</h3><div class="sum-line"><span>Cake subtotal</span><b>${money(total)}</b></div><p>Pickup is free. Delivery is ${money(state.settings.delivery_fee)}.</p><a class="button full" data-link href="/checkout">Continue to checkout ↗</a><p class="fineprint">${state.paymentsEnabled?'Secure payment with Paystack.'+(state.paymentMode==='test'?' Test mode: no real money collected.':''):'Online payment is not enabled. Orders are submitted as unpaid.'}</p></aside></div>`}</section>`)}
function checkout(){if(!state.user)return auth('login','/checkout');if(!cart.length)return cartPage();const total=cartDetails().reduce((n,i)=>n+i.unit*i.qty,0);return shell(`<section class="container section">${title('ALMOST TIME FOR CAKE','The sweet details.','Your order will be sent to the bakery for confirmation.')}<div class="checkout-layout"><form id="orderForm" class="panel"><h3>Contact & celebration</h3><div class="form-row"><label>Your name<input value="${esc(state.user.name)}" disabled></label><label>Email<input value="${esc(state.user.email)}" disabled></label></div><div class="form-row"><label>Phone number<input name="phone" type="tel" required autocomplete="tel" placeholder="080…"></label><label>Celebration date<input name="date" type="date" min="${state.minimumDate}" required></label></div><label>How would you like your cake?<select name="fulfilment" id="fulfilment"><option>Pickup</option><option>Delivery</option></select></label><label id="deliveryAddress" hidden>Delivery address<textarea name="address" placeholder="Street, area, city and a helpful landmark" autocomplete="street-address"></textarea></label><label>Special instructions<textarea name="notes" maxlength="1000" placeholder="Anything else we should know?"></textarea></label><div class="notice">${state.paymentsEnabled?'You’ll continue to Paystack to pay securely. Your order still needs bakery confirmation.'+(state.paymentMode==='test'?' TEST MODE: no real money will be collected.':''):'Online payment is not enabled. You can place an unpaid order for the bakery to confirm.'}</div><label class="check"><input type="checkbox" required> ${state.paymentsEnabled?'I understand this order is subject to bakery confirmation.':'I understand this order is unpaid and subject to bakery confirmation.'}</label><div class="form-error" role="alert"></div><button class="button full">${state.paymentsEnabled?'Continue to Paystack ↗':'Place unpaid order ↗'}</button></form><aside class="summary"><h3>Your celebration box</h3>${cartDetails().map(i=>`<div class="sum-line"><span>${i.qty} × ${esc(i.c?.name||'Unavailable cake')}</span><b>${money(i.unit*i.qty)}</b></div>`).join('')}<div class="sum-line"><span>Delivery</span><span id="feeDisplay">Free pickup</span></div><div class="sum-line total"><span>Total</span><b id="orderTotal">${money(total)}</b></div><p>Preparation: ${esc(state.settings.lead_days)} days minimum.</p></aside></div></section>`)}
function auth(mode='login',next){next=next||new URLSearchParams(location.search).get('next')||'';const signup=mode==='register',setup=mode==='setup';return shell(`<section class="auth-section"><div class="auth-intro"><div class="eyebrow">${setup?'WELCOME TO YOUR BAKERY STUDIO':'YOUR OWN LITTLE SLICE OF TEMMYD'}</div><h1>${setup?'Let’s open<br>your <em>studio.</em>':signup?'Sweet moments<br>start <em>here.</em>':'Welcome<br><em>back.</em>'}</h1><p>${setup?'Create the bakery owner’s account. Hosted setup requires the private token from your hosting environment.':signup?'Save your details, follow your orders and make every celebration a little sweeter.':'Your cakes, your celebrations, your little moments of joy. All in one place.'}</p></div><form id="authForm" data-mode="${mode}" data-next="${esc(next||new URLSearchParams(location.search).get('next')||'')}"><h2>${setup?'Create admin account':signup?'Create your account':'Sign in to your account'}</h2>${setup&&state.requiresSetupToken?'<label>Owner setup token<input name="setupToken" type="password" required autocomplete="off" placeholder="From your hosting environment"></label>':''}${signup||setup?'<label>Full name<input name="name" required maxlength="100" autocomplete="name"></label>':''}<label>Email address<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" required minlength="${signup||setup?'10':'1'}" maxlength="128" autocomplete="${signup||setup?'new-password':'current-password'}"></label>${signup||setup?'<p class="fineprint">Use at least 10 characters.</p>':''}<div class="form-error" role="alert"></div><button class="button full">${setup?'Create admin account':signup?'Create account':'Sign in'} ↗</button>${!setup?`<p class="auth-switch">${signup?'Already part of the family?':'New here?'} <a data-link href="/${signup?'login':'register'}${next?'?next='+encodeURIComponent(next):''}">${signup?'Sign in':'Create an account'}</a></p>`:''}${!signup&&!setup&&state.needsSetup?'<p class="auth-switch"><a data-link href="/setup">Bakery owner? Set up your admin account ↗</a></p>':''}</form></section>`)}
function account(){if(!state.user)return auth();return shell(`<section class="container section">${title('YOUR TEMMYD','Hello, '+esc(state.user.name.split(' ')[0])+'.','A home for your celebrations.')}<div class="account-grid"><a class="panel shortcut" data-link href="/account/orders"><span>↗</span><h2>Your orders</h2><p>Follow every sweet moment from oven to doorstep.</p></a><form class="panel" id="profileForm"><h3>Your details</h3><label>Full name<input name="name" value="${esc(state.user.name)}" required></label><label>Email<input value="${esc(state.user.email)}" disabled></label><details><summary>Change password</summary><label>Current password<input name="currentPassword" type="password" autocomplete="current-password"></label><label>New password<input name="password" type="password" minlength="10" maxlength="128" autocomplete="new-password"></label></details><div class="form-error"></div><button class="button">Save changes</button></form></div><button class="text-button" data-logout>Sign out</button></section>`)}
async function ordersPage(){if(!state.user)return auth('login','/account/orders');const orders=await api('/api/orders');return shell(`<section class="container section">${title('YOUR CELEBRATIONS','Your orders.','From our kitchen to your happy moment.')}<div class="order-list">${orders.map(o=>`<a class="order-card" data-link href="/account/orders/${o.id}"><div class="order-thumb"><img src="${esc(o.items[0]?.image)}" alt=""></div><div><small>${esc(o.id)} · ${date(o.created_at)}</small><h3>${o.items.map(i=>esc(i.name)).join(', ')}</h3><p>${o.fulfilment} · ${date(o.delivery_date)}</p></div><div>${badge(o.status)}<strong>${money(o.total)}</strong><small>${esc(o.payment)} · View order ↗</small></div></a>`).join('')||'<div class="empty"><h2>Your next celebration starts here.</h2><p>You haven’t placed any orders yet.</p><a class="button" href="/shop" data-link>Find your cake ↗</a></div>'}</div></section>`)}
async function orderPage(oid){if(!state.user)return auth('login','/account/orders/'+oid);const o=await api('/api/orders/'+oid);const steps=o.fulfilment==='Pickup'?['Placed','Confirmed','Baking','Ready','Collected']:['Placed','Confirmed','Baking','Ready','Out for delivery','Delivered'];const n=steps.indexOf(o.status);return shell(`<section class="container section"><a class="back" data-link href="/account/orders">← Your orders</a>${title('A LITTLE JOY IS ON ITS WAY','Your cake’s journey.')}<div class="section-heading"><div><b>${o.id}</b><p>Placed ${date(o.created_at)} · ${date(o.delivery_date)} ${o.fulfilment.toLowerCase()}</p></div><div>${badge(o.status)} ${badge(o.payment+(o.paymentDetails?.mode==='test'&&o.payment==='Paid'?' (test)':''))}</div></div>${o.status==='Cancelled'?'<div class="notice">This order has been cancelled. Contact the bakery about any payment or refund questions.</div>':`<div class="tracking-steps">${steps.map((s,i)=>`<div class="${i<=n?'done':''}"><span>${i<n?'✓':i+1}</span><p>${s}</p></div>`).join('')}</div>`}<div class="checkout-layout"><div class="panel"><h3>Updates from the bakery</h3><div class="timeline">${o.events.slice().reverse().map(e=>`<article><span class="dot"></span><small>${new Date(e.created_at).toLocaleString('en-NG')}</small><h4>${esc(e.status)}</h4><p>${esc(e.message)}</p></article>`).join('')}</div></div><aside class="summary"><h3>Your order</h3>${o.items.map(i=>`<div class="sum-line"><span>${i.qty} × ${esc(i.name)}<small>${i.size}-inch / equivalent box${i.message?' · '+esc(i.message):''}</small></span><b>${money(i.total)}</b></div>`).join('')}<div class="sum-line"><span>Delivery</span><b>${money(o.delivery_fee)}</b></div><div class="sum-line total"><span>Total</span><b>${money(o.total)}</b></div><p>${esc(o.fulfilment)}: ${esc(o.address||state.settings.address||'Pickup location to be confirmed by bakery')}</p>${o.tracking?`<div class="notice">${esc(o.tracking)}</div>`:''}<p>${esc(o.notes)}</p>${o.payment==='Unpaid'&&o.status!=='Cancelled'?(state.paymentsEnabled?`<button class="button full" data-pay-order="${o.id}">Pay ${money(o.total)} with Paystack ↗</button>${state.paymentMode==='test'?'<p class="fineprint">Test mode · No real money collected.</p>':''}${o.paymentDetails?`<button class="small-button full" data-check-payment="${esc(o.paymentDetails.reference)}">Check payment status</button>`:''}`:'<p class="fineprint">Payment is due. Online payment is not enabled.</p>'):''}${o.paymentDetails?`<p class="fineprint">${o.paymentDetails.mode==='test'?'TEST payment · ':''}Reference: ${esc(o.paymentDetails.reference)}</p>`:''}</aside></div></section>`)}
const adminNav=[['/admin','◫','Overview'],['/admin/cakes','♧','Cake collection'],['/admin/categories','▦','Categories'],['/admin/orders','▤','Orders'],['/admin/delivery','↗','Deliveries'],['/admin/customers','♙','Customers'],['/admin/settings','⚙','Settings'],['/admin/staff','♙','Staff'],['/admin/emails','✉','Emails']];
function studio(content){return `<div class="studio"><aside class="sidebar"><a data-link href="/admin">${logo()}</a><div class="studio-label">BAKERY STUDIO</div><nav>${adminNav.filter(([p])=>state.user.role==='admin'||state.user.role==='delivery'?state.user.role==='admin'||p==='/admin/delivery':!['/admin/customers','/admin/settings','/admin/staff','/admin/emails'].includes(p)).map(([p,i,l])=>`<a data-link href="${p}" class="${location.pathname===p?'active':''}"><span>${i}</span>${l}</a>`).join('')}</nav><div class="sidebar-bottom"><a data-link href="/">↗ View storefront</a><button data-logout>Sign out</button><small>${esc(state.user.email)}</small></div></aside><div class="studio-main"><div class="studio-top"><span>YOUR BAKERY, BEAUTIFULLY ORGANISED</span><div><i class="live-dot"></i> Live updates <b>${esc(state.user.name)}</b></div></div><div class="studio-content">${content}</div></div></div>`}
function studioTitle(k,h,sub,action=''){return `<div class="section-heading admin-heading"><div><div class="eyebrow">${k}</div><h1>${h}</h1><p>${sub}</p></div>${action}</div>`}
function orderTable(list){return `<div class="table-wrap"><table><thead><tr><th>Order / customer</th><th>Celebration</th><th>Total</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody>${list.map(o=>`<tr><td><b>${o.id}</b><small>${esc(o.customer)}</small></td><td>${date(o.delivery_date)}<small>${esc(o.fulfilment)}</small></td><td>${money(o.total)}</td><td>${badge(o.payment+(o.paymentDetails?.mode==='test'&&o.payment==='Paid'?' (test)':''))}</td><td>${badge(o.status)}</td><td><button class="small-button" data-order="${o.id}">Manage ↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty-cell">No orders here yet.</td></tr>'}</tbody></table></div>`}
async function adminPage(pathname){if(!state.user)return state.needsSetup?auth('setup'):auth('login',pathname);if(!isStaff())return shell(`<div class="container section">${title('ADMIN ACCESS REQUIRED','This area is for the bakery team.')}<a class="button" data-link href="/account">Go to my account</a></div>`);const page=state.user.role==='delivery'?'delivery':pathname.split('/')[2]||'overview';if(state.user.role==='manager'&&['customers','settings','staff','emails'].includes(page))return studio('<h1>Owner access required.</h1>');if(page==='staff')return staffPage();if(page==='emails')return emailPage();
if(page==='overview'){const orders=await api('/api/admin/orders');const active=orders.filter(o=>!['Cancelled','Delivered','Collected'].includes(o.status)),paid=orders.filter(o=>o.payment==='Paid'&&o.paymentDetails?.mode!=='test').reduce((n,o)=>n+o.total,0);return studio(`${studioTitle('A FRESH START','Hello, '+esc(state.user.name.split(' ')[0])+'.','Here’s what’s happening in your bakery today.','<a data-link href="/admin/cakes" class="button">Manage collection ↗</a>')}<div class="metric-grid"><div class="metric"><span>Recorded paid sales</span><h2>${money(paid)}</h2><small>Payments marked paid by admin</small></div><div class="metric"><span>Active orders</span><h2>${active.length}</h2><small>Celebrations in the making</small></div><div class="metric"><span>Awaiting confirmation</span><h2>${orders.filter(o=>o.status==='Placed').length}</h2><small>Ready for your attention</small></div><div class="metric"><span>Unpaid orders</span><h2>${orders.filter(o=>o.payment==='Unpaid'&&o.status!=='Cancelled').length}</h2><small>Follow up before fulfilment</small></div></div><div class="admin-banner"><div><span class="eyebrow">A LITTLE REMINDER</span><h2>Make every celebration feel special.</h2><p>Confirm new orders, keep your collection fresh, and share progress with your customers.</p></div><span class="banner-flower">✳</span></div><div class="panel flush"><div class="panel-heading"><h3>Recent orders</h3><a data-link href="/admin/orders">View all ↗</a></div>${orderTable(orders.slice(0,6))}</div><div class="notice">${state.paymentsEnabled?'Paystack is enabled in '+state.paymentMode+' mode. Test payments are excluded from recorded sales.':'Paystack is not enabled. Configure it in Settings to accept online payments.'}</div>`)}
if(page==='categories'){const list=await api('/api/admin/categories');return studio(`${studioTitle('ORGANISE YOUR SWEET COLLECTION','Categories.','Create a category, then add cakes and photos for customers to browse.')}<form id="categoryForm" class="panel category-create"><label>New category name<input name="name" required maxlength="60" placeholder="e.g. Wedding cakes"></label><button class="button">+ Create category</button><div class="form-error" role="alert"></div></form><div class="category-grid">${list.map(c=>`<article class="panel category-card"><span class="eyebrow">${c.cake_count} CAKE${c.cake_count===1?'':'S'} · ${c.visible_count} VISIBLE</span><h2>${esc(c.name)}</h2><p>${c.cake_count?'Add more cakes or manage this collection.':'Ready for its first cake. This category is already visible in the shop.'}</p><div class="category-actions"><button class="button" data-add-category="${esc(c.name)}">+ Add cake</button><a class="small-button" data-link href="/admin/cakes?category=${encodeURIComponent(c.name)}">View cakes ↗</a><button class="text-button" data-rename-category="${c.id}" data-category-name="${esc(c.name)}">Rename</button></div></article>`).join('')}</div>`)}
if(page==='cakes'){const selectedCategory=new URLSearchParams(location.search).get('category');let all=await api('/api/admin/cakes');if(selectedCategory)all=all.filter(c=>c.category===selectedCategory);return studio(`${studioTitle('YOUR RECIPE FOR HAPPINESS',selectedCategory?esc(selectedCategory)+'.':'Cake collection.','Add new favourites, upload photos, and keep your menu fresh.','<button class="button" id="newCake" data-category="'+esc(selectedCategory||'')+'">+ Add a cake</button>')}<div class="admin-cake-grid">${all.map(c=>`<article class="admin-cake"><img src="${esc(c.image)}" alt="${esc(c.name)}"><div><div class="section-heading">${badge(c.available?'Available':'Hidden')}<small>${esc(c.category)}</small></div><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="section-heading"><b>${money(c.price)}</b><button class="small-button" data-edit-cake="${c.id}">Edit cake ↗</button></div></div></article>`).join('')}</div>`) }
if(page==='orders'){const orders=await api('/api/admin/orders');window.adminOrders=orders;return studio(`${studioTitle('EVERY ORDER, A CELEBRATION','Orders.','Manage orders, record payments, and keep customers in the loop.')}<div class="admin-tools"><input id="orderSearch" placeholder="Search order, customer or email…" aria-label="Search orders"><select id="orderStatus" aria-label="Filter by status"><option value="">All statuses</option>${['Placed','Confirmed','Baking','Ready','Out for delivery','Delivered','Collected','Cancelled'].map(s=>`<option>${s}</option>`).join('')}</select><button class="small-button" id="exportOrders">Export CSV ↓</button></div><div class="panel flush" id="orderResults">${orderTable(orders)}</div>`)}
if(page==='delivery'){const orders=(await api('/api/admin/orders')).filter(o=>o.fulfilment==='Delivery'&&!['Cancelled','Delivered'].includes(o.status)).sort((a,b)=>a.delivery_date.localeCompare(b.delivery_date));return studio(`${studioTitle('FROM OUR KITCHEN TO THEIR DOOR','Delivery board.','Keep an eye on each delivery and share driver or delivery updates.')}<div class="delivery-board">${['Preparing','Ready','Out for delivery'].map((label,n)=>{const list=orders.filter(o=>n===0?['Placed','Confirmed','Baking'].includes(o.status):o.status===label);return `<section class="board-column"><h3>${label} <span>${list.length}</span></h3>${list.map(o=>`<article class="delivery-card"><small>${o.id}</small><h3>${esc(o.customer)}</h3><p>${esc(o.address)}</p><p>${date(o.delivery_date)} · ${esc(o.phone)}</p>${badge(o.status)}<button class="small-button full" data-order="${o.id}">Update delivery ↗</button></article>`).join('')||'<p class="empty-column">No deliveries in this stage.</p>'}</section>`}).join('')}</div>`)}
if(page==='customers'){const customers=await api('/api/admin/customers');return studio(`${studioTitle('THE PEOPLE BEHIND THE CELEBRATIONS','Your customers.','Customer accounts and their order history at a glance.')}<div class="panel flush"><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Email</th><th>Orders</th><th>Order value</th><th>Joined</th></tr></thead><tbody>${customers.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.email)}</td><td>${c.orders}</td><td>${money(c.total)}</td><td>${date(c.created_at)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty-cell">Customers appear here when they create an account.</td></tr>'}</tbody></table></div></div>`)}
if(page==='settings'){const s=state.settings;const pay=await api('/api/admin/payments');return studio(`${studioTitle('THE LITTLE DETAILS','Bakery settings.','Set your contact details, delivery fee and preparation time.')}<form id="settingsForm" class="panel settings-panel"><h3>Business details</h3><label>Business name<input name="business_name" value="${esc(s.business_name)}" required maxlength="100"></label><div class="form-row"><label>Contact email<input name="email" type="email" value="${esc(s.email)}"></label><label>Contact phone<input name="phone" value="${esc(s.phone)}"></label></div><label>Pickup address<textarea name="address">${esc(s.address)}</textarea></label><div class="form-row"><label>Delivery fee (₦)<input name="delivery_fee" type="number" min="0" max="1000000" step="1" required value="${s.delivery_fee}"></label><label>Minimum preparation days<input name="lead_days" type="number" min="1" max="60" required value="${s.lead_days}"></label></div><div class="form-error"></div><button class="button">Save settings ↗</button></form><form id="paymentSettingsForm" class="panel settings-panel" style="margin-top:25px"><h3>Paystack payments</h3><p class="fineprint">${pay.configured?'Key saved · '+pay.mode+' mode':'Add your Paystack test key to start.'}</p><label>Paystack secret key<input name="secret" type="password" autocomplete="new-password" placeholder="${pay.configured?'Leave blank to keep the saved key':'sk_test_…'}" ${pay.environmentManaged?'disabled':''}></label><p class="fineprint">Stored privately on the server. Never shown to customers. Use a test key for localhost; live keys require a public HTTPS site.</p><label>Website address<input name="origin" type="url" value="${esc(pay.origin||location.origin)}" required placeholder="https://your-domain.com"></label><label class="check"><input name="enabled" type="checkbox" ${pay.enabled?'checked':''}> Enable Paystack checkout</label><p class="fineprint">Once hosted, set your Paystack webhook URL to <b>${esc(pay.origin||location.origin)}/api/payments/webhook</b>. Localhost cannot receive Paystack webhooks; browser-return verification works locally.</p><div class="form-error" role="alert"></div><button class="button">Save payment settings ↗</button></form>`)}return studio('<h1>Page not found</h1>')}
async function render(){const version=++pageVersion;try{await session();[cakes,categories]=await Promise.all([api('/api/cakes'),api('/api/categories')]);if(filter!=='All'&&!categories.some(c=>c.name===filter))filter='All';let html;const p=location.pathname;if(p==='/staff/join')html=await joinStaff();else if(p.startsWith('/admin'))html=await adminPage(p);else if(p==='/')html=await home();else if(p==='/shop')html=shop();else if(p.startsWith('/cakes/'))html=product(p.split('/')[2]);else if(p==='/cart')html=cartPage();else if(p==='/checkout')html=checkout();else if(p==='/payment/return')html=await paymentReturn();else if(p==='/account')html=account();else if(p==='/account/orders')html=await ordersPage();else if(p.startsWith('/account/orders/'))html=await orderPage(p.split('/')[3]);else if(['/login','/register','/setup'].includes(p))html=p==='/setup'&&!state.needsSetup?auth('login','/admin'):auth(p.slice(1));else if(p==='/about')html=shell(`<section class="container about section">${title('MADE WITH A WHOLE LOT OF LOVE','Every cake tells <em>a story.</em>','At Temmyd Cakes, we make the little moments feel big and the big moments unforgettable.')}<div class="rose-panel"><h2>Thoughtful details.<br>Delicious layers. Your celebration.</h2><p>Choose a cake, make it yours, and follow along as we bring your celebration to life.</p><a class="button" data-link href="/shop">Find your cake ↗</a></div><div class="panel"><h3>Get in touch</h3><p>${esc(state.settings.email||'The bakery is setting up its contact details.')}</p><p>${esc(state.settings.phone)}</p><p>${esc(state.settings.address)}</p></div></section>`);else html=shell('<div class="container section"><h1>Oh crumbs. Page not found.</h1><a href="/shop" data-link>Back to the cakes ↗</a></div>');if(version!==pageVersion)return;$('#app').innerHTML=html;bind()}catch(e){$('#app').innerHTML=shell(`<div class="container section"><h1>We couldn’t load this page.</h1><p>${esc(e.message)}</p><a href="/" data-link>Back home ↗</a></div>`)}}
function formHandler(selector,fn){const form=$(selector);if(form)form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button[type="submit"],button:not([type])');const error=form.querySelector('.form-error');if(error)error.textContent='';if(button)button.disabled=true;try{await fn(Object.fromEntries(new FormData(form)),form)}catch(e){if(error)error.textContent=e.message;else toast(e.message)}finally{if(button)button.disabled=false}}}
function bind(){
if($('#emailTest'))$('#emailTest').onclick=async()=>{try{await api('/api/admin/email/test',{method:'POST',body:{}});toast('Email test created.');render()}catch(e){toast(e.message)}};
document.querySelectorAll('[data-email-preview]').forEach(b=>b.onclick=async()=>{try{const m=await api('/api/admin/email/preview/'+b.dataset.emailPreview);$('#modal').innerHTML=`<div class="modal-heading"><h2>${esc(m.subject)}</h2><button class="icon-button" data-close aria-label="Close">×</button></div><p>To: ${esc(m.recipient)}</p><p class="notice">Local preview · No email sent</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.6">${esc(m.content)}</pre>`;$('#modal').showModal()}catch(e){toast(e.message)}});

formHandler('#inviteForm',async f=>{const result=await api('/api/admin/staff/invites',{method:'POST',body:f});const box=$('#inviteResult');box.hidden=false;box.querySelector('input').value=location.origin+result.joinPath;box.querySelector('input').select();toast(result.emailMode==='sending'?'Invitation queued for email.':'Invitation preview created. No email sent.');});
formHandler('#acceptStaff',async()=>{await api('/api/staff/accept',{method:'POST',body:{token:new URLSearchParams(location.search).get('token')}});go('/admin');});
document.querySelectorAll('[data-staff-save]').forEach(b=>b.onclick=async()=>{try{await api('/api/admin/staff/'+b.dataset.staffSave,{method:'PATCH',body:{role:document.getElementById('role-'+b.dataset.staffSave).value}});toast('Staff access updated. They must sign in again.');render()}catch(e){toast(e.message)}});
document.querySelectorAll('[data-invite-revoke]').forEach(b=>b.onclick=async()=>{try{await api('/api/admin/staff/invites/'+b.dataset.inviteRevoke,{method:'DELETE'});toast('Invitation revoked.');render()}catch(e){toast(e.message)}});
const search=$('#cakeSearch');if(search)search.oninput=()=>{query=search.value;$('#cakeResults').innerHTML=cards(filtered())};const productForm=$('#productForm');if(productForm){const c=cakes.find(c=>c.id===location.pathname.split('/')[2]);productForm.oninput=()=>$('#productPrice').textContent=money(Math.round(c.price*({6:1,8:1.5,10:2}[productForm.size.value]))*(+productForm.qty.value||1));productForm.onsubmit=e=>{e.preventDefault();cart.push({cakeId:c.id,size:+productForm.size.value,qty:+productForm.qty.value,message:productForm.message.value.trim()});save();toast('A little happiness added to your box ♡');render()}}
formHandler('#authForm',async(f,form)=>{await api('/api/'+form.dataset.mode,{method:'POST',body:f});await session();const next=form.dataset.next;go(next.startsWith('/')&&!next.startsWith('//')?next:isStaff()?'/admin':'/account')});
formHandler('#orderForm',async(f)=>{const o=await api('/api/orders',{method:'POST',body:{...f,items:cart}});cart=[];save();go('/account/orders/'+o.id);if(state.paymentsEnabled){try{await startPayment(o.id)}catch(e){toast(e.message+' Your order is saved; retry from its order page.')}}else toast('Order received. The bakery will confirm the details.')});const fulfilment=$('#fulfilment');if(fulfilment)fulfilment.onchange=()=>{const delivery=fulfilment.value==='Delivery';$('#deliveryAddress').hidden=!delivery;$('#orderForm').address.required=delivery;$('#feeDisplay').textContent=delivery?money(state.settings.delivery_fee):'Free pickup';$('#orderTotal').textContent=money(cartDetails().reduce((n,i)=>n+i.unit*i.qty,0)+(delivery?+state.settings.delivery_fee:0))};
formHandler('#paymentSettingsForm',async(f,form)=>{await api('/api/admin/payments',{method:'PATCH',body:{...f,enabled:form.enabled.checked}});form.secret.value='';toast('Paystack settings saved.');render()});formHandler('#profileForm',async f=>{await api('/api/profile',{method:'PATCH',body:f});toast('Your details have been updated.');render()});formHandler('#settingsForm',async f=>{await api('/api/admin/settings',{method:'PATCH',body:f});toast('Bakery settings saved.');render()});formHandler('#categoryForm',async f=>{await api('/api/admin/categories',{method:'POST',body:f});toast('Category created. Add your first cake to it.');render()});if($('#newCake'))$('#newCake').onclick=()=>cakeModal(null,$('#newCake').dataset.category);const searchOrders=()=>{const term=$('#orderSearch').value.toLowerCase(),status=$('#orderStatus').value;$('#orderResults').innerHTML=orderTable(window.adminOrders.filter(o=>(!status||o.status===status)&&(o.id+' '+o.customer+' '+o.email).toLowerCase().includes(term)))};if($('#orderSearch')){$('#orderSearch').oninput=searchOrders;$('#orderStatus').onchange=searchOrders;$('#exportOrders').onclick=()=>{const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"';const rows=[['Order','Customer','Email','Date','Fulfilment','Total NGN','Status','Payment'],...window.adminOrders.map(o=>[o.id,o.customer,o.email,o.delivery_date,o.fulfilment,o.total,o.status,o.payment])];const url=URL.createObjectURL(new Blob([rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download='temmyd-orders.csv';a.click();URL.revokeObjectURL(url)}}}
async function cakeModal(cid,categoryName){try{const all=await api('/api/admin/cakes');categories=await api('/api/categories');const c=all.find(c=>c.id===cid)||{name:'',description:'',price:'',category:categoryName||categories[0]?.name||'',image:'',available:1,featured:0};$('#modal').innerHTML=`<div class="modal-heading"><h2>${cid?'Edit your cake':'A new little favourite'}</h2><button class="icon-button" data-close aria-label="Close">×</button></div><form id="cakeForm"><label>Cake name<input name="name" required maxlength="100" value="${esc(c.name)}"></label><label>Description<textarea name="description" required maxlength="1000">${esc(c.description)}</textarea></label><div class="form-row"><label>Base price (₦)<input type="number" name="price" min="100" max="10000000" step="1" required value="${c.price}"></label><label>Category<select name="category" required><option value="">Choose a category</option>${categories.map(cat=>`<option value="${esc(cat.name)}" ${cat.name===c.category?'selected':''}>${esc(cat.name)}</option>`).join('')}</select></label></div><label>Upload cake photo<input type="file" id="cakeFile" accept="image/png,image/jpeg,image/webp"></label><p class="fineprint">JPG, PNG or WebP, up to 4 MB. Or enter an HTTPS image URL below.</p><label>Photo URL<input name="image" id="cakeImage" required value="${esc(c.image)}"></label><img class="upload-preview" id="imagePreview" ${c.image?'src="'+esc(c.image)+'"':'hidden'} alt="Cake photo preview"><div class="form-row"><label class="check"><input type="checkbox" name="available" ${c.available?'checked':''}> Available in shop</label><label class="check"><input type="checkbox" name="featured" ${c.featured?'checked':''}> Feature on homepage</label></div><div class="form-error" role="alert"></div><button class="button full">${cid?'Save cake':'Add cake to collection'} ↗</button></form>`;$('#modal').showModal();let uploading=false;$('#cakeImage').onchange=()=>{$('#imagePreview').src=$('#cakeImage').value;$('#imagePreview').hidden=false};$('#cakeFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;const error=$('#cakeForm .form-error');try{if(file.size>4000000)throw Error('Choose an image smaller than 4 MB.');uploading=true;const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read image.'));reader.readAsDataURL(file)});const result=await api('/api/admin/upload',{method:'POST',body:{image}});$('#cakeImage').value=result.url;$('#imagePreview').src=result.url;$('#imagePreview').hidden=false;error.textContent=''}catch(e){error.textContent=e.message}finally{uploading=false}};formHandler('#cakeForm',async(f,form)=>{if(uploading)throw Error('Wait for the photo upload to finish.');await api('/api/admin/cakes'+(cid?'/'+cid:''),{method:cid?'PATCH':'POST',body:{...f,available:form.available.checked,featured:form.featured.checked}});$('#modal').close();toast('Cake collection updated.');render()})}catch(e){toast(e.message)}}
async function orderModal(oid){try{const o=await api('/api/orders/'+oid);if(state.user.role==='delivery')return deliveryModal(o);const drivers=o.fulfilment==='Delivery'?await api('/api/admin/drivers'):[];const options=o.fulfilment==='Pickup'?['Placed','Confirmed','Baking','Ready','Collected','Cancelled']:['Placed','Confirmed','Baking','Ready','Out for delivery','Delivered','Cancelled'];$('#modal').innerHTML=`<div class="modal-heading"><div><small>${o.id}</small><h2>One sweet celebration.</h2></div><button class="icon-button" data-close aria-label="Close">×</button></div><div class="order-contact"><h3>${esc(o.customer)}</h3><p>${esc(o.email)} · ${esc(o.phone)}</p><p>${o.fulfilment} · ${date(o.delivery_date)}</p><p>${esc(o.address)}</p></div>${o.items.map(i=>`<div class="sum-line"><span>${i.qty} × ${esc(i.name)}<small>${i.size} inch / box equivalent · ${esc(i.message)}</small></span><b>${money(i.total)}</b></div>`).join('')}<div class="sum-line total"><span>Total incl. delivery</span><b>${money(o.total)}</b></div>${o.notes?`<div class="notice">Customer note: ${esc(o.notes)}</div>`:''}<form id="manageOrder"><div class="form-row"><label>Order status<select name="status">${options.map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Payment record<select name="payment" ${state.user.role!=='admin'?'disabled':''}>${['Unpaid','Paid','Refunded'].map(s=>`<option ${o.payment===s?'selected':''}>${s}</option>`).join('')}</select></label></div>${o.fulfilment==='Delivery'?`<label>Assigned delivery staff<select name="assignedTo"><option value="">Unassigned</option>${drivers.map(d=>`<option value="${d.id}" ${o.assigned_to===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label>`:''}<label>Delivery / pickup details<textarea name="tracking" maxlength="600" placeholder="Driver name, contact, delivery window or pickup instructions">${esc(o.tracking)}</textarea></label><label>Update for the customer<textarea name="message" maxlength="1000" placeholder="Your cake is in the oven! We’re getting it ready for your celebration."></textarea></label><p class="fineprint">Updates are visible to the customer. Recording payment does not collect or refund money.</p><div class="form-error"></div><button class="button full">Save order update ↗</button></form>`;$('#modal').showModal();formHandler('#manageOrder',async f=>{await api('/api/admin/orders/'+oid,{method:'PATCH',body:f});$('#modal').close();toast('Order updated. Your customer can see the latest status.');render()})}catch(e){toast(e.message)}}
document.addEventListener('click',async e=>{const link=e.target.closest('a[data-link]');if(link&&!e.ctrlKey&&!e.metaKey){e.preventDefault();go(link.getAttribute('href'));return}const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-close'))$('#modal').close();if(b.hasAttribute('data-filter')){filter=b.dataset.filter;render()}if(b.hasAttribute('data-logout')){await api('/api/logout',{method:'POST'});await session();go(location.pathname==='/staff/join'?'/login?next='+encodeURIComponent(location.pathname+location.search):'/login')}if(b.hasAttribute('data-remove')){cart.splice(+b.dataset.remove,1);save();render()}if(b.hasAttribute('data-qty')){const i=cart[+b.dataset.qty];i.qty=Math.min(20,+i.qty+ +b.dataset.delta);if(i.qty<1)cart.splice(+b.dataset.qty,1);save();render()}if(b.dataset.addCategory)cakeModal(null,b.dataset.addCategory);if(b.dataset.renameCategory)categoryModal(b.dataset.renameCategory,b.dataset.categoryName);if(b.dataset.editCake)cakeModal(b.dataset.editCake);if(b.dataset.payOrder){b.disabled=true;try{await startPayment(b.dataset.payOrder)}catch(e){toast(e.message);b.disabled=false}}if(b.dataset.checkPayment){b.disabled=true;try{const result=await api('/api/payments/verify',{method:'POST',body:{reference:b.dataset.checkPayment}});toast(result.paid?'Payment verified.':'Payment is not completed yet.');render()}catch(e){toast(e.message);b.disabled=false}}if(b.dataset.order)orderModal(b.dataset.order)});window.onpopstate=()=>render();render();

function categoryModal(cid,name){$('#modal').innerHTML=`<div class="modal-heading"><h2>Rename category</h2><button class="icon-button" data-close aria-label="Close">×</button></div><form id="renameCategoryForm"><label>Category name<input name="name" required maxlength="60" value="${esc(name)}"></label><p class="fineprint">All cakes in this category will move to the new name automatically.</p><div class="form-error" role="alert"></div><button class="button full">Save category ↗</button></form>`;$('#modal').showModal();formHandler('#renameCategoryForm',async f=>{await api('/api/admin/categories/'+cid,{method:'PATCH',body:f});$('#modal').close();toast('Category renamed.');render()})}

async function startPayment(orderId){const result=await api('/api/payments/initialize',{method:'POST',body:{orderId}});if(result.paid){toast('Payment already verified.');render();return}const target=new URL(result.authorizationUrl);if(target.protocol!=='https:'||target.hostname!=='checkout.paystack.com')throw Error('Invalid checkout destination.');location.assign(target.href)}
async function paymentReturn(){const reference=new URLSearchParams(location.search).get('reference');if(!state.user)return auth('login',location.pathname+location.search);if(!reference)return shell('<div class="container section"><h1>No payment reference found.</h1><a href="/account/orders" data-link>View your orders ↗</a></div>');try{const result=await api('/api/payments/verify',{method:'POST',body:{reference}});return shell(`<section class="container section"><div class="panel"><div class="eyebrow">PAYSTACK PAYMENT</div><h1>${result.paid?'Payment verified.':'Payment not completed yet.'}</h1><p>${result.mode==='test'?'Test mode — no real money was collected.':''} ${result.paid?'Your order has been updated. The bakery will confirm the celebration details.':'Your order is saved. You can check payment status or try again from your order page.'}</p><a class="button" data-link href="/account/orders/${esc(result.orderId)}">View your order ↗</a></div></section>`)}catch(e){return shell(`<section class="container section"><h1>We couldn’t verify payment.</h1><p>${esc(e.message)}</p><p>Check your order status before trying another payment.</p><a class="button" data-link href="/account/orders">View orders ↗</a></section>`)}}

async function staffPage(){const {members,invites}=await api('/api/admin/staff');return studio(`${studioTitle('YOUR BAKERY TEAM','Staff access.','Invite trusted people and choose what they can manage.')}<div class="panel"><h3>Invite a team member</h3><p>Managers manage cakes, categories and orders. Delivery staff see only their assigned deliveries. Only the owner manages staff, settings and payment records.</p><form id="inviteForm"><div class="form-row"><label>Email address<input name="email" type="email" required maxlength="254"></label><label>Role<select name="role"><option value="manager">Manager</option><option value="delivery">Delivery staff</option></select></label></div><div class="form-error" role="alert"></div><button class="button">Create invitation ↗</button></form><div id="inviteResult" class="notice" hidden><label>Copy this invitation link<input readonly aria-label="Invitation link" onclick="this.select()"></label><p>In preview mode, copy and send it privately to the invited person. Links expire after seven days and work once. Email delivery depends on your email configuration; check Emails for status. The person must sign in or register using the invited email.</p></div></div><div class="panel" style="margin-top:24px"><h3>Team members</h3><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Access</th><th></th></tr></thead><tbody>${members.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.email)}</td><td>${m.role==='admin'?'Owner':`<select id="role-${m.id}" aria-label="Role for ${esc(m.name)}"><option value="manager" ${m.role==='manager'?'selected':''}>Manager</option><option value="delivery" ${m.role==='delivery'?'selected':''}>Delivery staff</option><option value="customer">Remove staff access</option></select>`}</td><td>${m.role==='admin'?'':`<button class="small-button" data-staff-save="${m.id}">Save access</button>`}</td></tr>`).join('')}</tbody></table></div><p class="fineprint">Changing access signs the person out and removes their delivery assignments.</p></div><div class="panel" style="margin-top:24px"><h3>Pending invitations</h3>${invites.map(i=>`<div class="sum-line"><span>${esc(i.email)} · ${esc(i.role)}<small>Expires ${date(i.expires)}</small></span><button class="small-button" data-invite-revoke="${i.id}">Revoke</button></div>`).join('')||'<p>No pending invitations.</p>'}</div>`)}
async function joinStaff(){const token=new URLSearchParams(location.search).get('token');if(!token)return shell('<section class="container section"><h1>Invitation link required.</h1><p>Ask the bakery owner for your invitation.</p></section>');if(!state.user)return auth('login',location.pathname+location.search);return shell(`<section class="container section"><div class="panel"><h1>Join the bakery team.</h1><p>Signed in as ${esc(state.user.email)}. Accept only if the bakery owner invited this email address.</p><form id="acceptStaff"><div class="form-error" role="alert"></div><button class="button">Accept staff invitation ↗</button></form><button class="text-button" data-logout>Sign out to use another account</button></div></section>`)}
function deliveryModal(o){const options=[o.status,...(o.status==='Ready'?['Out for delivery']:o.status==='Out for delivery'?['Delivered']:[])];$('#modal').innerHTML=`<div class="modal-heading"><h2>Delivery ${esc(o.id)}</h2><button class="icon-button" data-close aria-label="Close">×</button></div><h3>${esc(o.customer)}</h3><p>${esc(o.phone)} · ${date(o.delivery_date)}</p><p>${esc(o.address)}</p>${o.items.map(i=>`<p>${i.qty} × ${esc(i.name)} · ${i.size} inch / box equivalent</p>`).join('')}<form id="deliveryForm"><label>Delivery status<select name="status">${options.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label><p class="fineprint">The bakery must mark the order Ready before dispatch.</p><label>Delivery details<textarea name="tracking" maxlength="600">${esc(o.tracking)}</textarea></label><label>Update for customer<textarea name="message" maxlength="1000"></textarea></label><div class="form-error" role="alert"></div><button class="button full">Save delivery update ↗</button></form>`;$('#modal').showModal();formHandler('#deliveryForm',async f=>{await api('/api/admin/orders/'+o.id,{method:'PATCH',body:f});$('#modal').close();toast('Delivery updated.');render()})}

async function emailPage(){const e=await api('/api/admin/email');return studio(`${studioTitle('KEEP CUSTOMERS IN THE LOOP','Email notifications.','Order updates, payment notifications and staff invitations.')}<div class="panel"><h3>${e.enabled?'Sending through '+esc(e.provider):'Preview mode — no emails sent'}</h3><p>${e.enabled?'Messages are submitted to your email provider automatically. Sent means accepted by the provider; it does not guarantee inbox delivery.':'Emails are saved for review. New orders and order updates generate previews automatically.'}</p><p>Provider: ${esc(e.provider)}. ${e.configured?'Sender configured.':'Connect your provider API key and verify your sender address to enable delivery.'}</p><button class="button" id="emailTest">${e.enabled?'Send a test to my email':'Create a test preview'} ↗</button><a class="small-button" data-link href="/admin/emails">Refresh status</a></div><div class="panel" style="margin-top:24px"><h3>Recent notifications</h3><div class="table-wrap"><table><thead><tr><th>Recipient / subject</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody>${e.messages.map(m=>`<tr><td><b>${esc(m.recipient)}</b><small>${esc(m.subject)}</small>${m.last_error?`<small>${esc(m.last_error)}</small>`:''}</td><td>${badge(m.status)}</td><td>${date(m.created_at)}</td><td>${m.status==='preview'&&['localhost','127.0.0.1'].includes(location.hostname)?`<button class="small-button" data-email-preview="${m.id}">Read preview ↗</button>`:''}</td></tr>`).join('')||'<tr><td colspan="4">No notifications yet. Create a test preview or place a new order.</td></tr>'}</tbody></table></div><p class="fineprint">Preview emails are never sent automatically when delivery is enabled later. Only the owner can access this page. Staff invitation previews contain private, single-use links.</p></div>`)}
